#include "id.h"
#include <string.h>
static IdProtocol id;
enum{AT,PUT,SEQUENCE,INVOKE,VALUE,CONTINUE,FROMWORD,FRAMES,WORDOF,LOW32,ADD,LOOP,MARK,CALLBACK,LOOKUPMARK,TARGETMARK,NATIVE_CALLBACK,LOOKUP_CALLBACK,TARGET,HELPER,COUNTS,RESET,TICK,NAMES};
static const IdLiteral literals[]={LIT("at:"),LIT("at:put:"),LIT("sequence"),LIT("invokeOn:arguments:"),LIT("value"),LIT("continueWithBudget:"),LIT("fromWord:"),LIT("liveFrameCount"),LIT("wordOf:"),LIT("low32"),LIT("addMethod"),LIT("loop"),LIT("mark:"),LIT("callback"),LIT("lookupMark"),LIT("targetMark"),LIT("nativeCallback"),LIT("lookupCallback"),LIT("seamTarget"),LIT("duringLookup"),LIT("counts"),LIT("reset"),LIT("tick")};
static Oop names[NAMES];static size_t marks[3],reentry_rejections;
static Oop call(Oop r,size_t sel,const Oop*a,size_t n){return id.message(id.root,r,names[sel],a,n);}
static Oop get(Oop c,size_t i){Oop n=id_size(i);return call(c,AT,&n,1);}
static Oop put(Oop c,size_t i,Oop v){Oop a[]={id_size(i),v};return call(c,PUT,a,2);}
#define CHECK(v) do{Oop failed_=(v);if(id_fault(failed_))return failed_;}while(0)
static Oop mark(Oop root,Oop c,Oop r,const Oop*a,size_t n){if(n!=1)return id.invalid;for(size_t i=0;i<3;i++)if(a[0]==names[CALLBACK+i]){marks[i]++;return r;}return id.invalid;}
static Oop reset(Oop root,Oop c,Oop r,const Oop*a,size_t n){if(n)return id.invalid;memset(marks,0,sizeof(marks));reentry_rejections=0;return r;}
static Oop counts(Oop root,Oop c,Oop r,const Oop*a,size_t n){if(n)return id.invalid;Oop v[]={id_size(marks[0]),id_size(marks[1]),id_size(marks[2]),id_size(reentry_rejections)};return call(id.root,SEQUENCE,v,4);}
/* c = [running Machine, source callback Block, Integer factory]. */
static Oop native_callback(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 if(n)return id.invalid;Oop one=id_size(1);Oop budget=call(get(c,2),FROMWORD,&one,1);if(id_fault(budget))return budget;
 Oop rejected=call(get(c,0),CONTINUE,&budget,1);if(!id_fault(rejected))return id.invalid;reentry_rejections++;
 return call(get(c,1),VALUE,0,0);
}
/* c = [original lookup Method, original receiver]. A callback runs on the
   SAME receiver/arity as the pending source call, before its method is chosen. */
static Oop lookup_callback(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 if(n!=1)return id.invalid;
 if(a[0]==names[TARGET]){CHECK(call(get(c,1),HELPER,0,0));}
 Oop args=call(id.root,SEQUENCE,a,n);if(id_fault(args))return args;
 Oop input[]={r,args};return call(get(c,0),INVOKE,input,2);
}
/* Per-Machine context = [remaining, type, stop Method, ticks]. */
static Oop tick(Oop root,Oop c,Oop r,const Oop*a,size_t n){
 if(n)return id.invalid;Oop remaining=get(c,0);if(id_fault(remaining)||!((uintptr_t)remaining&1)||id_unbox(remaining)==0)return id.invalid;
 size_t next=id_unbox(remaining)-1;CHECK(put(c,0,id_size(next)));
 Oop count=get(c,3);if(id_fault(count))return count;CHECK(put(c,3,id_size(id_unbox(count)+1)));
